state bill=84.5 tip="18%" people=3
derive tipRate={tip == '15%' ? 0.15 : tip == '18%' ? 0.18 : 0.2}
derive tipTotal={bill * tipRate}
derive grandTotal={bill + tipTotal}
derive perPerson={grandTotal / people}
card
