  grid min=140 gap=12
    stat label="Tip total" value={money(tipTotal)}
    stat label="Grand total" value={money(grandTotal)}
    stat label="Per person" value={money(perPerson)} tone=accent
  text "{money(bill)} bill · {tip} tip · {people} people" tone=muted

